-- Conteos principales y filas repetidas
SELECT COUNT(*) AS filas,
       COUNT(DISTINCT order_id) AS ordenes,
       COUNT(DISTINCT customer_id) AS clientes,
       COUNT(*) - COUNT(DISTINCT row_id) AS row_id_duplicados
FROM tem12m_nelson.superstore_staging;

-- Total de celdas vacías y valores que incumplen las reglas de calidad
SELECT COUNT(CASE WHEN TRIM(row_id) IS NULL OR TRIM(row_id) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(order_id) IS NULL OR TRIM(order_id) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(order_date) IS NULL OR TRIM(order_date) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(ship_date) IS NULL OR TRIM(ship_date) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(ship_mode) IS NULL OR TRIM(ship_mode) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(customer_id) IS NULL OR TRIM(customer_id) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(customer_name) IS NULL OR TRIM(customer_name) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(segment) IS NULL OR TRIM(segment) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(country) IS NULL OR TRIM(country) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(city) IS NULL OR TRIM(city) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(state) IS NULL OR TRIM(state) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(postal_code) IS NULL OR TRIM(postal_code) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(region) IS NULL OR TRIM(region) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(product_id) IS NULL OR TRIM(product_id) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(category) IS NULL OR TRIM(category) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(sub_category) IS NULL OR TRIM(sub_category) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(product_name) IS NULL OR TRIM(product_name) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(sales) IS NULL OR TRIM(sales) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(quantity) IS NULL OR TRIM(quantity) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(discount) IS NULL OR TRIM(discount) = '' THEN 1 END) + COUNT(CASE WHEN TRIM(profit) IS NULL OR TRIM(profit) = '' THEN 1 END) + COUNT(CASE WHEN UNIX_TIMESTAMP(TRIM(order_date), 'M/d/yyyy') IS NULL THEN 1 END) + COUNT(CASE WHEN UNIX_TIMESTAMP(TRIM(ship_date), 'M/d/yyyy') IS NULL THEN 1 END) + COUNT(CASE WHEN CAST(sales AS DOUBLE) <= 0 THEN 1 END) + COUNT(CASE WHEN CAST(discount AS DOUBLE) < 0 OR CAST(discount AS DOUBLE) > 1 THEN 1 END) + COUNT(CASE WHEN UNIX_TIMESTAMP(TRIM(ship_date), 'M/d/yyyy') < UNIX_TIMESTAMP(TRIM(order_date), 'M/d/yyyy') THEN 1 END) AS hallazgos_calidad
FROM tem12m_nelson.superstore_staging;
